B.a_m=s(["\ubcf8\uc778\uc740 \ub2e4\uc774\ube59 \uc7a5\uc18c\uc758 \ud2b9\uc131\uc5d0 \ub530\ub77c \uc751\uae09\uc758\ub8cc\uc2dc\uc124 \ubc0f \uc7ac\uc555\uce58\ub8cc\uc2dc\uc124\uc5d0 \ub300\ud55c \uc811\uadfc\uc774 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00 \ub610\ub294 \uad6c\uc870 \ub2f4\ub2f9\uc790\uac00 \uc801\uc808\ud55c \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \uc218\ud589\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.","\uc774 \uc870\ud56d\uc740 \ubc95\ub839\uc0c1 \uc694\uad6c\ub418\ub294 \ubcc4\ub3c4\uc758 \uc758\ub8cc \ub3d9\uc758\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],t.s)
B.anN=new A.e7("\uc81c8\uc870. \uc751\uae09\uc0c1\ud669\uc5d0 \ub300\ud55c \uc774\ud574",B.a_m,B.A)
B.a_r=s(["\ubcf8\uc778\uc740 \ubcf8 \ub3d9\uc758\uc11c\uc758 \uc804\uccb4 \ub0b4\uc6a9\uc744 \uc77d\uace0 \uc774\ud574\ud558\uc600\uc73c\uba70, \uad81\uae08\ud55c \uc0ac\ud56d\uc5d0 \ub300\ud574 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\ub97c \uac00\uc84c\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac15\uc694 \uc5c6\uc774 \uc790\ubc1c\uc801\uc778 \uc758\uc0ac\ub85c \ubcf8 \ub3d9\uc758\uc11c\uc5d0 \uc11c\uba85\ud569\ub2c8\ub2e4."],t.s)
B.anX=new A.e7("\uc81c9\uc870. \ucd5c\uc885 \ud655\uc778",B.a_r,B.A)
B.a19=s([B.anJ,B.anO,B.anT,B.anG,B.anD,B.anS,B.anN,B.anX],t.H9)
B.ans=new A.hl("risk","\uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uc758 \uc555\ub825\uc190\uc0c1\xb7\uac10\uc555\ubcd1\xb7\uc7a5\ube44\xb7\ud658\uacbd \ub4f1 \uace0\uc720 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uc218\uc6a9\ud569\ub2c8\ub2e4.")
B.anx=new A.hl("health","\uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud788 \uace0\uc9c0\ud558\uace0 \uc758\ud559 \uc9c4\uc220\uc11c\xb7\ud544\uc694 \uc2dc \uc758\ub8cc\ud655\uc778\uc5d0 \uc751\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
B.anr=new A.hl("rules","\uac15\uc0ac \uc9c0\uc2dc\xb7\uc548\uc804\uc218\uce59\xb7\ubc84\ub514 \uc2dc\uc2a4\ud15c\xb7\ube44\uc0c1\uc808\ucc28\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.")
B.rt=new A.hl("apdi","APDI\uc640 \uad50\uc721\uae30\uad00\xb7\uac15\uc0ac\uc758 \uad00\uacc4\uac00 \ub3c5\ub9bd\uc801\uc77c \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
B.rv=new A.hl("voluntary","\uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud558\uba70, \ubcf8 \ub3d9\uc758\ub294 \ubc95\ub839\uc0c1 \uc815\ub2f9\ud55c \uad8c\ub9ac\ub97c \ud3ec\uad04 \ud3ec\uae30\ud558\uc9c0 \uc54a\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
B.ant=new A.hl("emergency","\uc751\uae09\uad6c\uc870\xb7\uc774\uc1a1 \uc870\uce58\uc5d0 \ub3d9\uc758\ud558\uba70, \uc7ac\uc555\uce58\ub8cc \uc811\uadfc\uc774 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
B.ru=new A.hl("read","\ub3d9\uc758\uc11c \uc804\uccb4\ub97c \uc77d\uace0 \uc774\ud574\ud55c \ub4a4 \uc790\ubc1c\uc801\uc73c\ub85c \uc11c\uba85\ud569\ub2c8\ub2e4.")
B.Zz=s([B.ans,B.anx,B.anr,B.rt,B.rv,B.ant,B.ru],t.OZ)
